insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000041401', '$r(1)=(2,3,-2)$.', 'Uma reta espacial fica determinada por um ponto e um vetor diretor não nulo. A forma paramétrica soma ao ponto um múltiplo real da direção; por isso, substituir o parâmetro ou comparar componentes permite verificar cada resultado sem ambiguidade.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000414011', '40000000-0000-4000-8000-000000041401', 'Substitua t', '$r(1)=(1,1,-1)+1(1,2,-1).$', 1), ('70000000-0000-4000-8000-000000414012', '40000000-0000-4000-8000-000000041401', 'Distribua', '$1(1,2,-1)=(1,2,-1).$', 2), ('70000000-0000-4000-8000-000000414013', '40000000-0000-4000-8000-000000041401', 'Some', '$r(1)=(2,3,-2).$', 3)
