insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000414501', '40000000-0000-4000-8000-000000041450', 'Imponha z igual a zero', '$20-2t=0.$', 1), ('70000000-0000-4000-8000-000000414502', '40000000-0000-4000-8000-000000041450', 'Encontre t', '$t=10.$', 2), ('70000000-0000-4000-8000-000000414503', '40000000-0000-4000-8000-000000041450', 'Calcule o ponto', '$r(10)=(20,-9,0).$', 3)
