insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000041550', '50000000-0000-4000-8000-000000415501') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000041550', '30000000-0000-4000-8000-000000000214', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000415501', '40000000-0000-4000-8000-000000041550', 'Substitua as coordenadas paramétricas da reta no plano.', 1), ('60000000-0000-4000-8000-000000415502', '40000000-0000-4000-8000-000000041550', 'A soma das três coordenadas será n mais 3t.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000041550', '$t=11$.', 'Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000415501', '40000000-0000-4000-8000-000000041550', 'Escreva as coordenadas', '$x=t, y=10+t, z=t.$', 1), ('70000000-0000-4000-8000-000000415502', '40000000-0000-4000-8000-000000041550', 'Substitua no plano', '$t+(10+t)+t=43.$', 2), ('70000000-0000-4000-8000-000000415503', '40000000-0000-4000-8000-000000041550', 'Resolva', '$3t=33 \Rightarrow t=11.$', 3)
