insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000041601', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000207', 'multiple_choice', 'medium', 'published', 'A reta r tem vetor diretor $d=(1,1,-1)$. Qual vetor pode ser diretor de uma reta paralela a r?')
